"""Task-centric v0.4 conference dashboard."""

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CTMAO Agent Conference</title><style>
*{box-sizing:border-box}body{margin:0;min-width:320px;color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,textarea,select{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.46}h2{font-size:16px;margin:0 0 12px}.muted{color:var(--muted)}
/* Tile layout adapted from the Synthetic Visuals 5 three-panel reference. */
:root{--bg:#05070b;--bg2:#080d14;--panel:#0b1018;--panel2:#0f172a;--line:#1a2332;--ink:#e2e8f0;--muted:#94a3b8;--cyan:#22d3ee;--gold:#fbbf24;--red:#f87171;--green:#34d399;--shadow:none}
html,body{min-height:100%;background:var(--bg)}body{background:var(--bg);font-size:14px}.shell{width:100%;max-width:none;margin:0;padding:0}
.panel{background:var(--panel2);border:1px solid var(--line);border-radius:10px}.muted,.meta-label{color:var(--muted)}.status{border:1px solid var(--line);border-radius:999px;padding:7px 12px;font-weight:750;white-space:nowrap}.status[data-state="running"],.status[data-state="queued"]{color:var(--cyan);border-color:var(--cyan)}.status[data-state="completed"]{color:var(--green);border-color:var(--green)}.status[data-state="failed"],.status[data-state="cancelled"]{color:var(--red);border-color:var(--red)}
.task-source{display:inline-flex;align-items:center;gap:7px;color:var(--cyan);font-weight:800}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:currentColor}.objective{font-weight:750;overflow-wrap:anywhere}.stage{margin-top:6px;color:var(--muted)}
.composer[hidden]{display:none}.composer textarea{width:100%;resize:vertical;padding:11px 12px;color:var(--ink);border:1px solid #2a394a;border-radius:8px;outline:none}.composer textarea:focus,.voice-row select:focus-visible,.btn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}.actions,.controls{display:flex;gap:8px;flex-wrap:wrap}.btn{padding:9px 12px;color:var(--ink);border:1px solid #2d4052;border-radius:8px;font-weight:700}
.participant-top{display:block}.participant-role{color:var(--muted)}.participant-state{text-transform:uppercase;letter-spacing:.08em;font-weight:800}.voice-row{display:flex;gap:7px}.voice-row select{width:100%;min-width:0;padding:6px;color:var(--ink);border:1px solid #2a394a;border-radius:7px}.voice-row button{flex:none}.now-speaker,.speaker{color:var(--gold);font-weight:850}.now-text{display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.empty{display:grid;place-items:center;text-align:center;color:var(--muted)}.message{overflow-wrap:anywhere}.message-head{display:flex;justify-content:space-between;gap:10px;margin-bottom:7px}.kind{color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.body p{margin:0 0 8px}.body p:last-child{margin-bottom:0}.body ul,.body ol{margin:6px 0 8px;padding-left:21px}.body h3{font-size:14px;margin:9px 0 4px}.show-more{margin-top:9px;padding:0;background:none;border:0;color:var(--cyan);font-weight:750}.provenance{margin-top:10px;color:var(--muted);font-size:11px}.provenance summary,details.tech>summary{cursor:pointer}
.evidence-intro{margin:7px 0;color:var(--muted)}.evidence-list{display:grid;gap:7px;margin:9px 0 0;padding:0;list-style:none}.evidence-list li{padding:8px 9px;border:1px solid var(--line);border-radius:7px;background:#0a111b}.evidence-list strong{display:block;color:var(--ink);font-size:11px}.evidence-list code{display:block;margin-top:4px;color:var(--muted);font:10px/1.45 ui-monospace,Consolas,monospace;overflow-wrap:anywhere}.evidence-list .link-label{color:var(--cyan)}
.tech-grid{display:grid;gap:12px;margin-top:12px}.tech-box{min-height:120px;max-height:220px;overflow:auto;padding:10px;border:1px solid var(--line);border-radius:8px;font:11px/1.45 ui-monospace,Consolas,monospace}.log-row{padding:4px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.tree-row{padding:4px 0;overflow-wrap:anywhere}
header.topbar{position:sticky;top:0;z-index:10;display:flex;align-items:center;justify-content:space-between;min-height:72px;margin:0;padding:12px 24px;background:linear-gradient(180deg,#0b1018,var(--bg));border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:12px;min-width:0}.brand-mark{display:grid;place-items:center;width:38px;height:38px;flex:none;border-radius:9px;background:linear-gradient(135deg,var(--cyan),#e879f9);color:#061019;font-size:23px;font-weight:900;box-shadow:0 0 20px rgba(34,211,238,.22)}
.brand h1{margin:0;font-size:18px;letter-spacing:.01em}.brand .muted{font-size:12px}.status{font-size:12px;background:#10201f;border-color:#24584f}
.main{display:grid;grid-template-columns:minmax(260px,300px) minmax(340px,1fr) minmax(340px,440px);min-height:calc(100vh - 72px)}
.pane{min-width:0;padding:20px;border-right:1px solid var(--line)}.pane:last-child{border-right:0}.pane-title{display:flex;align-items:center;gap:8px;margin:0 0 17px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.pane-title:before{content:"";width:4px;height:14px;border-radius:3px;background:var(--cyan)}
.panel{background:var(--panel2);border-color:var(--line);border-radius:10px}.taskbar{padding:16px;margin-bottom:14px;box-shadow:none}.task-head{display:block}.task-source{font-size:11px}.objective{font-size:17px;line-height:1.35;margin-top:11px}.stage{font-size:13px}.conference-short{margin-top:11px;font-size:11px}.dot{box-shadow:0 0 10px currentColor}
.composer{display:block;padding:15px;margin:0 0 14px;box-shadow:none}.field-label{display:block;margin:0 0 8px;color:var(--muted);font-size:12px}.composer textarea{min-height:112px;background:var(--panel);border-color:#29394d}.actions{flex-direction:row;margin-top:12px}.actions .btn{flex:1}.btn{border-color:#2d4052;background:#121d2b;font-size:12px}.btn.primary{background:linear-gradient(135deg,var(--cyan),#60a5fa);color:#051018;border:0}.btn.danger{background:#281b22}.btn:hover:not(:disabled){border-color:var(--cyan)}
.notice{min-height:0;padding:11px 12px;margin-bottom:14px;background:rgba(251,191,36,.07);border:1px solid rgba(251,191,36,.2);border-radius:8px;color:var(--gold);font-size:12px}.notice:empty{display:none}.notice.error{border-color:rgba(248,113,113,.3);background:rgba(248,113,113,.08)}
.session-card{padding:15px;box-shadow:none}.session-card h2{font-size:13px}.meta-list{font-size:12px}.meta-list>div+div{padding-top:8px;border-top:1px solid var(--line)}
.flow-pane{background:radial-gradient(ellipse at 50% 30%,#0b1520,var(--bg) 74%)}.flow-board{padding:15px;border:1px solid var(--line);border-radius:12px;background-color:#070c13;background-image:linear-gradient(rgba(34,211,238,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(34,211,238,.035) 1px,transparent 1px);background-size:40px 40px}.flow-intro{margin:0 0 14px;color:var(--muted);font-size:12px}
.participants{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:0}.participant{position:relative;padding:15px;background:#0f172a;border:1px solid #253448;border-radius:10px;min-height:148px}.participant:before{content:"";position:absolute;top:15px;right:15px;width:9px;height:9px;border:2px solid var(--role-color,var(--cyan));border-radius:50%;background:#0f172a}.participant[data-id="Researcher"]{--role-color:var(--cyan)}.participant[data-id="Builder"]{--role-color:var(--green)}.participant[data-id="Reviewer"]{--role-color:#e879f9}.participant[data-id="Moderator"]{--role-color:var(--gold)}.participant.active,.participant[data-state="working"]{border-color:var(--role-color);box-shadow:0 0 0 1px var(--role-color),0 0 24px rgba(34,211,238,.1)}.participant[data-state="working"]:before,.participant.active:before{background:var(--role-color);box-shadow:0 0 12px var(--role-color)}.participant-name{padding-right:18px;color:var(--role-color);font-size:15px}.participant-role{font-size:12px;min-height:38px;margin:6px 0 8px}.participant-state{color:var(--role-color);font-size:10px}.voice-row{margin-top:11px}.voice-row select{background:#0b1018;border-color:#2a394a;font-size:11px}.voice-row button{font-size:11px}
.live-card{padding:15px;margin-top:15px;box-shadow:none}.live-card h2{font-size:13px}.now-speaker{font-size:18px}.now-text{font-size:12px}.controls .btn{flex:1}.controls{margin-top:12px}
details.tech{margin-top:15px;padding:13px 15px;box-shadow:none}details.tech>summary{font-size:12px}.tech-grid{grid-template-columns:1fr}.tech-box{background:#080e16;border-color:var(--line)}
.transcript-pane{display:flex;flex-direction:column;min-height:calc(100vh - 72px);background:#070a10}.transcript-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.transcript-note{margin:0 0 14px;color:var(--muted);font-size:12px}.conversation-panel{flex:1;min-height:0;padding:0;border:0;background:transparent;box-shadow:none}.conversation{min-height:420px;max-height:calc(100vh - 165px);overflow:auto;padding-right:5px}.empty{min-height:360px}.message{width:100%;padding:14px;margin-bottom:11px;background:var(--panel2);border:1px solid #243346;border-radius:10px}.message.decision{background:#211e16;border-color:#765a2a}.message-head{font-size:13px}.kind{font-size:10px}.body{font-size:13px}.provenance{padding-top:8px;border-top:1px solid var(--line)}.provenance div{overflow-wrap:anywhere;line-height:1.5}
@media(max-width:1080px){.main{grid-template-columns:minmax(240px,280px) minmax(0,1fr)}.transcript-pane{grid-column:1/-1;min-height:0;border-top:1px solid var(--line)}.conversation{max-height:none;min-height:280px}.pane:nth-child(2){border-right:0}}
@media(max-width:700px){header.topbar{position:static;padding:12px 16px}.brand h1{font-size:16px}.brand .muted{display:none}.main{grid-template-columns:1fr}.pane{padding:16px;border-right:0;border-bottom:1px solid var(--line)}.flow-pane,.transcript-pane{grid-column:auto}.participants{grid-template-columns:repeat(2,minmax(0,1fr))}.participant{min-height:150px}.conversation{min-height:250px}.status{white-space:normal}}
@media(max-width:440px){.participants{grid-template-columns:1fr}.participant{min-height:0}.actions{flex-wrap:wrap}.actions .btn{min-width:110px}}
</style></head><body><div class="shell">
<header class="topbar"><div class="brand"><div class="brand-mark" aria-hidden="true">◈</div><div><h1>Agent Conference</h1><div class="muted">One Codex task, its real participants, and a concise public record.</div></div></div><div id="run-status" class="status" data-state="idle">Idle</div></header>
<main class="main"><section class="pane setup-pane"><div class="pane-title">Task and controls</div>
<section id="taskbar" class="panel taskbar"><div class="task-head"><div><div id="task-source" class="task-source"><span class="dot"></span><span>Local conference</span></div><div id="task-objective" class="objective">No task attached yet</div><div id="stage" class="stage">Start a conference below or invoke it from Codex.</div></div><div id="conference-short" class="conference-short muted"></div></div></section>
<section id="composer" class="panel composer"><label class="field-label" for="objective">Conference objective</label><textarea id="objective" maxlength="4000" aria-label="Conference objective" placeholder="What should the agents discuss and solve?"></textarea><div class="actions"><button id="start" class="btn primary">Start conference</button><button id="cancel" class="btn danger" disabled>Cancel</button></div></section>
<div id="notice" class="notice" role="status">Do not enter passwords, API keys, or other secrets.</div>
<section class="panel session-card"><h2>Task session</h2><div class="meta-list"><div><span class="meta-label">Provider</span><br><span id="provider">Loading…</span></div><div><span class="meta-label">Conference</span><br><span id="session">Waiting</span></div></div></section></section>
<section class="pane flow-pane"><div class="pane-title">Live workflow</div><div class="flow-board"><p class="flow-intro">Researcher and Builder work independently. Reviewer checks their results; Moderator makes the decision.</p><div id="participants" class="participants"></div></div>
<section class="panel live-card"><h2>Now speaking</h2><div id="now-speaker" class="now-speaker">Nobody yet</div><div id="now-text" class="now-text muted">Audio follows the same redacted text shown in the conversation.</div><div class="controls"><button id="audio" class="btn">Audio on</button><button id="pause" class="btn">Pause voice</button></div></section>
<details class="panel tech"><summary>Technical events and delegation tree</summary><div class="tech-grid"><div><h2>Activity</h2><div id="log" class="tech-box"></div></div><div><h2>Tasks</h2><div id="tree" class="tech-box"></div></div></div></details></section>
<section class="pane transcript-pane"><div class="pane-title">Public record</div><div class="transcript-head"><h2>Conference conversation</h2></div><p class="transcript-note">Each message includes an inspectable source trail.</p><div class="conversation-panel"><div id="conversation" class="conversation" aria-live="polite"><div id="empty" class="empty"><div><strong>No public messages yet</strong><p>Participant contributions will appear here as the task progresses.</p></div></div></div></div></section></main>
</div><script>
const token=new URLSearchParams(location.search).get('token');
const defaultRoles={Researcher:'Facts, assumptions, and uncertainty',Builder:'Concrete implementation approach',Reviewer:'Risks, objections, and validation',Moderator:'Synthesis and next actions'};
const participants=new Map(),voices=new Map(),speakerMute=new Set(),usedVoices=new Set(),spoken=new Set(),tasks=new Map();let currentConferenceId=null,audioOn=true,voicePaused=false,speaking=false,speechQueue=[];
function hash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function allVoices(){return 'speechSynthesis'in window?[...speechSynthesis.getVoices()].sort((a,b)=>a.name.localeCompare(b.name)):[]}
function chosenVoice(id){const all=allVoices();if(voices.has(id)){const found=all.find(v=>v.name===voices.get(id));if(found)return found;voices.delete(id)}if(!all.length)return null;const pool=id==='Moderator'?all:(all.length>1?all.slice(1):all);let selected=pool[hash(id)%pool.length];for(const v of pool){if(!usedVoices.has(v.name)){selected=v;break}}voices.set(id,selected.name);usedVoices.add(selected.name);return selected}
function voiceSelect(select,id){const current=voices.get(id)||'';select.replaceChildren(new Option('Automatic voice',''));for(const voice of allVoices())select.add(new Option(voice.name,voice.name));select.value=current}
function participantCard(info){const id=info.participant_id;if(participants.has(id))return participants.get(id);const card=document.createElement('article');card.className='panel participant';card.dataset.id=id;card.innerHTML='<div class="participant-top"><div class="participant-name"></div><div class="participant-role"></div></div><div class="participant-state"></div><div class="voice-row"><select></select><button class="btn">Mute</button></div>';card.querySelector('.participant-name').textContent=info.display_name||id;card.querySelector('.participant-role').textContent=info.responsibility||defaultRoles[id]||'Conference participant';const select=card.querySelector('select'),mute=card.querySelector('button');select.setAttribute('aria-label',`Voice for ${id}`);voiceSelect(select,id);select.onchange=()=>{if(select.value)voices.set(id,select.value);else voices.delete(id)};mute.onclick=()=>{speakerMute.has(id)?speakerMute.delete(id):speakerMute.add(id);mute.textContent=speakerMute.has(id)?'Unmute':'Mute'};document.querySelector('#participants').append(card);participants.set(id,card);setAgentState(id,info.state||'waiting');return card}
function renderParticipants(items){for(const info of items||[])participantCard(info);for(const info of items||[])setAgentState(info.participant_id,info.state||'waiting')}
function setAgentState(id,state){const card=participants.get(id)||participantCard({participant_id:id,display_name:id,responsibility:defaultRoles[id]});card.dataset.state=state||'waiting';card.querySelector('.participant-state').textContent=String(state||'waiting').replaceAll('_',' ')}
function setActive(id,on){const card=participants.get(id);if(card)card.classList.toggle('active',on)}
function resetSpeech(){speechQueue=[];speaking=false;spoken.clear();for(const card of participants.values())card.classList.remove('active');if('speechSynthesis'in window)speechSynthesis.cancel()}
function resetConference(id){currentConferenceId=id||null;document.querySelector('#conversation').innerHTML='<div id="empty" class="empty"><div><strong>No public messages yet</strong><p>Participant contributions will appear here as the task progresses.</p></div></div>';document.querySelector('#log').textContent='';document.querySelector('#tree').textContent='';tasks.clear();resetSpeech();document.querySelector('#now-speaker').textContent='Nobody yet';document.querySelector('#now-text').textContent='Audio follows the same redacted text shown in the conversation.';for(const card of participants.values())setAgentState(card.dataset.id,'waiting')}
function pump(){if(speaking||!audioOn||voicePaused||!speechQueue.length||!('speechSynthesis'in window))return;const message=speechQueue.shift();if(speakerMute.has(message.speaker_id)){pump();return}const utterance=new SpeechSynthesisUtterance(message.text),voice=chosenVoice(message.speaker_id);if(voice)utterance.voice=voice;utterance.rate=.92+(hash(message.speaker_id)%17)/100;utterance.pitch=.92+(hash(message.speaker_id+'p')%17)/100;speaking=true;setActive(message.speaker_id,true);document.querySelector('#now-speaker').textContent=message.speaker_id;document.querySelector('#now-text').textContent=message.text;utterance.onend=utterance.onerror=()=>{setActive(message.speaker_id,false);speaking=false;pump()};speechSynthesis.speak(utterance)}
function speak(message){const key=[...message.source_event_ids].sort().join(',');if(spoken.has(key)||!audioOn)return;spoken.add(key);if(speechQueue.length>=20)speechQueue.shift();speechQueue.push(message);pump()}
function inlineText(parent,text){const parts=text.split(/(\*\*[^*]+\*\*)/g);for(const part of parts){if(part.startsWith('**')&&part.endsWith('**')){const strong=document.createElement('strong');strong.textContent=part.slice(2,-2);parent.append(strong)}else parent.append(document.createTextNode(part))}}
function renderBody(container,text,expanded=false){container.textContent='';const limited=!expanded&&text.length>900,textToShow=limited?text.slice(0,900).trimEnd()+'…':text,lines=textToShow.split(/\r?\n/);let list=null;for(const raw of lines){const line=raw.trim();if(!line){list=null;continue}const bullet=line.match(/^[-*]\s+(.+)/),number=line.match(/^\d+[.)]\s+(.+)/);if(bullet||number){const tag=number?'ol':'ul';if(!list||list.tagName.toLowerCase()!==tag){list=document.createElement(tag);container.append(list)}const li=document.createElement('li');inlineText(li,(bullet||number)[1]);list.append(li);continue}list=null;if(/^#{1,4}\s+/.test(line)){const h=document.createElement('h3');inlineText(h,line.replace(/^#{1,4}\s+/,''));container.append(h)}else{const p=document.createElement('p');inlineText(p,line);container.append(p)}}if(limited){const button=document.createElement('button');button.className='show-more';button.textContent='Show full message';button.onclick=()=>renderBody(container,text,true);container.append(button)}}
function addMessage(message){
  if(document.getElementById('m-'+message.turn_id))return;
  document.querySelector('#empty')?.remove();
  const box=document.createElement('article');
  box.id='m-'+message.turn_id;
  box.className='message'+(message.message_kind==='decision'?' decision':'');
  box.innerHTML='<div class="message-head"><span class="speaker"></span><span class="kind"></span></div><div class="body"></div><details class="provenance"><summary>Provenance</summary><div class="evidence-content"></div></details>';
  box.querySelector('.speaker').textContent=message.speaker_id;
  box.querySelector('.kind').textContent=message.message_kind||'statement';
  renderBody(box.querySelector('.body'),message.text);
  const evidence=box.querySelector('.evidence-content');
  const records=message.source_evidence_records||[];
  const intro=document.createElement('p');
  intro.className='evidence-intro';
  intro.textContent=`${records.length} verified event${records.length===1?'':'s'} · ${message.transformation_name}@${message.transformation_version}`;
  evidence.append(intro);
  const list=document.createElement('ol');list.className='evidence-list';
  for(const record of records){
    const item=document.createElement('li');
    const label=document.createElement('strong');
    label.textContent=`${record.agent_path?.at(-1)||record.worker_id||'Conference'} · ${record.event_type}`;
    item.append(label);
    for(const [name,value] of [['Event',record.event_id],['Cause',record.causation_event_id],['Inputs',(record.source_event_ids||[]).join(', ')],['Correlation',record.correlation_id],['Evidence',`${record.origin} · ${record.evidence}`],['Source',JSON.stringify(record.provenance||{})]]){
      if(!value)continue;
      const line=document.createElement('code');
      line.textContent=`${name}: ${value}`;
      if(name==='Cause'||name==='Inputs')line.className='link-label';
      item.append(line);
    }
    list.append(item);
  }
  evidence.append(list);
  document.querySelector('#conversation').append(box);
  box.scrollIntoView({block:'nearest'});
  setAgentState(message.speaker_id,'contributed');
  document.querySelector('#now-speaker').textContent=message.speaker_id;
  document.querySelector('#now-text').textContent=message.text;
  speak(message);
}
function technical(e){const row=document.createElement('div');row.className='log-row';row.textContent=`#${e.sequence} ${e.event_type} — ${e.summary.length>180?e.summary.slice(0,180)+'…':e.summary}`;const log=document.querySelector('#log');log.append(row);while(log.children.length>160)log.firstChild.remove();if(e.task_id){const path=e.agent_path||[],old=tasks.get(e.task_id),depth=path.length,label=path.at(-1)||e.worker_id||e.task_id;tasks.set(e.task_id,{id:e.task_id,parent:e.parent_task_id||old?.parent||'',label:!old||depth>=old.depth?label:old.label,depth:Math.max(depth,old?.depth||0),status:e.status||old?.status||'active'});renderTree()}}
function renderTree(){const box=document.querySelector('#tree');box.textContent='';const children=new Map();for(const n of tasks.values()){const p=n.parent||'';if(!children.has(p))children.set(p,[]);children.get(p).push(n)}function walk(parent,depth){for(const n of children.get(parent)||[]){const row=document.createElement('div');row.className='tree-row';row.style.paddingLeft=`${depth*15}px`;row.textContent=`${depth?'↳':'●'} ${n.label} — ${n.status}`;box.append(row);walk(n.id,depth+1)}}walk('',0);if(!box.children.length)box.textContent='No delegated task facts yet.'}
function showNotice(text,kind=''){const box=document.querySelector('#notice');box.textContent=text||'';box.className='notice'+(kind?' '+kind:'')}
function applyConference(c){if(!c)return;if(c.conference_id&&c.conference_id!==currentConferenceId)resetConference(c.conference_id);renderParticipants(c.participants||Object.entries(defaultRoles).map(([id,responsibility])=>({participant_id:id,display_name:id,responsibility,state:'waiting'})));document.querySelector('#provider').textContent=c.provider||'Unknown';document.querySelector('#session').textContent=c.conference_id?c.conference_id.slice(0,12)+'…':'Waiting';document.querySelector('#conference-short').textContent=c.conference_id?'Run '+c.conference_id.slice(0,8):'';document.querySelector('#task-objective').textContent=c.objective||'No task attached yet';document.querySelector('#stage').textContent=c.stage||'Waiting';document.querySelector('#task-source span:last-child').textContent=c.mode==='codex'?'Attached to a Codex task':'Local interactive conference';document.querySelector('#composer').hidden=c.mode==='codex';const status=c.status||'idle',statusBox=document.querySelector('#run-status');statusBox.textContent=status.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase());statusBox.dataset.state=status;const busy=['queued','running','cancelling'].includes(status);document.querySelector('#start').disabled=busy;document.querySelector('#cancel').disabled=!busy;for(const info of c.participants||[])setAgentState(info.participant_id,info.state);if(c.error)showNotice(c.error,'error');else if(c.warning)showNotice(c.warning,'warning');else if(c.mode==='codex')showNotice('This view follows public, source-backed updates from the originating Codex task.');if(['completed','failed','cancelled'].includes(status)){resetSpeech();document.querySelector('#now-speaker').textContent=status==='completed'?'Conference complete':'Nobody speaking';document.querySelector('#now-text').textContent=c.warning||c.error||'The full public transcript remains available.'}}
async function state(){try{const response=await fetch(`/api/state?token=${encodeURIComponent(token)}`,{cache:'no-store'});if(!response.ok)return;const value=await response.json();applyConference(value.conference)}catch(e){showNotice('The local conference connection is unavailable.','error')}}
async function command(path,body={}){const response=await fetch(`${path}?token=${encodeURIComponent(token)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok)throw new Error(value.error||'Request failed');return value}
document.querySelector('#start').onclick=async()=>{const objective=document.querySelector('#objective').value.trim();showNotice('');if(!objective){showNotice('Enter an objective first.','error');return}try{const result=await command('/api/runs',{objective});applyConference(result);document.querySelector('#objective').value=''}catch(e){showNotice(e.message,'error')}};
document.querySelector('#cancel').onclick=async()=>{try{applyConference(await command('/api/runs/cancel'))}catch(e){showNotice(e.message,'error')}};
document.querySelector('#audio').onclick=e=>{audioOn=!audioOn;if(!audioOn)resetSpeech();e.target.textContent=audioOn?'Audio on':'Audio off'};
document.querySelector('#pause').onclick=e=>{voicePaused=!voicePaused;if('speechSynthesis'in window){voicePaused?speechSynthesis.pause():speechSynthesis.resume()}e.target.textContent=voicePaused?'Resume voice':'Pause voice'};
if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=()=>document.querySelectorAll('.participant').forEach(card=>voiceSelect(card.querySelector('select'),card.dataset.id));
const es=new EventSource(`/events?token=${encodeURIComponent(token)}`);es.onmessage=frame=>{const payload=JSON.parse(frame.data);if(payload.conference_id&&payload.conference_id!==currentConferenceId)resetConference(payload.conference_id);technical(payload.event);for(const message of payload.messages)addMessage(message);state()};es.onerror=()=>showNotice('Live updates were interrupted; reconnecting…','warning');es.onopen=()=>{if(document.querySelector('#notice').textContent.startsWith('Live updates'))showNotice('');};state();setInterval(state,1500);
</script></body></html>"""
